def Ghostscript(tile, size, fp, scale=1):
    """Render an image using Ghostscript"""
    decoder, tile, offset, data = tile[0]
    length, bbox = data
    scale = int(scale) or 1
    orig_size = size
    orig_bbox = bbox
    size = (size[0] * scale, size[1] * scale)
    bbox = [bbox[0], bbox[1], bbox[2] * scale, bbox[3] * scale]
    import tempfile, os, subprocess
    out_fd, file = tempfile.mkstemp()
    os.close(out_fd)
    command = ["gs",
               "-q",
               "-g%dx%d" % size,
               "-r%d" % (72*scale),
               "-dNOPAUSE -dSAFER",
               "-sDEVICE=ppmraw",
               "-sOutputFile=%s" % file,
            ]
    if gs_windows_binary is not None:
        if gs_windows_binary is False:
            raise WindowsError('Unable to locate Ghostscript on paths')
        command[0] = gs_windows_binary
    try:
        gs = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE)
        if bbox[0] != 0 or bbox[1] != 0:
            gs.stdin.write(("%d %d translate\n" % (-bbox[0], -bbox[1])).encode('ascii'))
        fp.seek(offset)
        while length > 0:
            s = fp.read(8192)
            if not s:
                break
            length = length - len(s)
            gs.stdin.write(s)
        gs.stdin.close()
        status = gs.wait()
        if status:
            raise IOError("gs failed (status %d)" % status)
        im = Image.core.open_ppm(file)
    finally:
        try: os.unlink(file)
        except: pass
    return im
    def load_djpeg(self):
        import tempfile, os
        f, path = tempfile.mkstemp()
        os.close(f)
        if os.path.exists(self.filename):
            os.system("djpeg '%s' >'%s'" % (self.filename, path))
        else:
            raise ValueError("Invalid Filename")
        try:
            self.im = Image.core.open_ppm(path)
        finally:
            try: os.unlink(path)
            except: pass
        self.mode = self.im.mode
        self.size = self.im.size
        self.tile = []

